import { finding } from '../../engine/checks/helpers/findings.mjs';
import { workflowFiles } from '../../engine/checks/helpers/github-workflows.mjs';

// A single | between non-| characters is a shell pipe; || is the or-operator.
const PIPE = /(^|[^|])\|([^|]|$)/;

